def dichotomie(l, x):
    gauche = 0
    droite = len(l) - 1

    while gauche <= droite:
        milieu = (gauche + droite) // 2

        if l[milieu] == x:
            return milieu
        elif l[milieu] < x:
            gauche = milieu + 1
        else:
            droite = milieu - 1

    return -1
```

